:root {
  --tag-bg: #f4ead0;
  --tag-border: #8b6a2e;
  --tag-header-bg: #5a3e1b;
  --tag-header-text: #f4ead0;
  --tag-number-text: #d4a84b;
  --tag-label-text: #f4ead0;
  --divider-color: #c9a55a;
  --name-main-color: #3b2608;
  --name-sub-color: #7a5c2e;
  --spec-label-color: #8b6a2e;
  --spec-value-color: #3b2608;
  --spec-item-bg: #ede0b8;
  --footer-bg: #e8d9ae;
  --craftsman-label-color: #8b6a2e;
  --craftsman-name-color: #3b2608;
  --badge-bg: #5a3e1b;
  --badge-text: #d4a84b;
}

.workshop-tag {
  width: 420px;
  background-color: var(--tag-bg);
  border: 2px solid var(--tag-border);
  border-radius: 6px;
  overflow: hidden;
  margin: 20px auto;
}

.tag-header {
  background-color: var(--tag-header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.tag-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--tag-label-text);
  text-transform: uppercase;
}

.tag-number {
  font-size: 12px;
  font-weight: 600;
  color: var(--tag-number-text);
  letter-spacing: 1px;
}

.tag-body {
  padding: 16px 18px 12px;
}

.instrument-name {
  text-align: center;
  margin-bottom: 12px;
}

.name-main {
  font-size: 22px;
  font-weight: 700;
  color: var(--name-main-color);
  margin: 0 0 4px 0;
  line-height: 1.1;
  letter-spacing: 0.5px;
}

.name-sub {
  font-size: 12px;
  font-weight: 400;
  color: var(--name-sub-color);
  margin: 0;
  letter-spacing: 0.5px;
}

.tag-divider {
  height: 2px;
  background-color: var(--divider-color);
  border-radius: 1px;
  margin-bottom: 12px;
}

.specs-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 8px;
}

.spec-item {
  background-color: var(--spec-item-bg);
  border: 1px solid var(--divider-color);
  border-radius: 4px;
  padding: 8px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.spec-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--spec-label-color);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  text-align: center;
}

.spec-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--spec-value-color);
  text-align: center;
}

.tag-footer {
  background-color: var(--footer-bg);
  border-top: 2px solid var(--divider-color);
  padding: 10px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.craftsman-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.craftsman-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--craftsman-label-color);
}

.craftsman-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--craftsman-name-color);
}

.status-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 5px 12px;
  border-radius: 3px;
  text-transform: uppercase;
}
